class Solution {
public:
    vector<string> removeSubfolders(vector<string>& folder) {
        sort(folder.begin(), folder.end());
        vector<string> res;
        for (int k = 0; k < (int)folder.size(); k++) {
            string& f = folder[k];
            if (!res.empty()) {
                string prefix = res.back() + "/";
                if (f.compare(0, prefix.size(), prefix) == 0) continue;
            }
            res.push_back(f);
        }
        return res;
    }
};
